/**
 * Progressive Web App pieces that every private app can reuse: the web manifest
 * and the service worker's source. Browser-safe and Node-safe (pure strings and
 * objects) so an Astro endpoint can emit both at build time:
 *
 *   // src/pages/manifest.webmanifest.ts
 *   export const GET = () => new Response(JSON.stringify(webManifest({...})), {...});
 *   // src/pages/sw.js.ts
 *   export const GET = () => new Response(serviceWorkerSource({...}), {...});
 *
 * Icon files are made by `@factory/common/pwa-icons` (Node + sharp, build time).
 * Browser-side helpers (register, install, badge) are in `@factory/common/pwa-client`.
 *
 * What the worker caches, and what it must never cache, is decided HERE and
 * tested (test/pwa.test.mjs), because a private app is where a cache can leak:
 * only the static shell (HTML/JS/CSS/images, which contain no private data — the
 * data is fetched by script at run time) is stored; every URL matching `bypass`
 * goes straight to the network and is never written to a cache.
 */

export interface PwaIcon {
  src: string;
  sizes: string;
  type: string;
  purpose?: "any" | "maskable" | "monochrome";
}

export interface PwaShortcut {
  name: string;
  /** Absolute path, base included. */
  url: string;
  short_name?: string;
  description?: string;
}

export interface WebManifestOptions {
  name: string;
  shortName: string;
  description: string;
  lang?: string;
  /** Absolute path (base included) the app opens at, e.g. "/app/". */
  startUrl: string;
  /** Absolute path the app owns; navigation outside it opens in the browser. Defaults to `startUrl`. */
  scope?: string;
  /** Stable identity of the install. Defaults to `startUrl`. */
  id?: string;
  /** Colour of the title bar / status bar. */
  themeColor: string;
  /** Colour of the splash screen. */
  backgroundColor: string;
  icons: PwaIcon[];
  shortcuts?: PwaShortcut[];
  display?: "standalone" | "minimal-ui" | "fullscreen";
  /** Defaults to "portrait": a phone app used at the desk or standing up. */
  orientation?: "any" | "portrait" | "landscape";
}

export function webManifest(o: WebManifestOptions) {
  const scope = o.scope ?? o.startUrl;
  if (!o.startUrl.startsWith(scope)) throw new Error(`manifest: start_url ${o.startUrl} is outside scope ${scope}`);
  const sizes = new Set(o.icons.filter((i) => (i.purpose ?? "any") === "any").map((i) => i.sizes));
  // Chrome installs only with a 192 and a 512 icon; fail the build, not the install.
  for (const need of ["192x192", "512x512"]) if (!sizes.has(need)) throw new Error(`manifest: missing a ${need} icon`);
  if (!o.icons.some((i) => i.purpose === "maskable")) throw new Error("manifest: add a maskable icon (Android crops icons to a shape)");
  return {
    id: o.id ?? o.startUrl,
    name: o.name,
    short_name: o.shortName,
    description: o.description,
    lang: o.lang ?? "it",
    start_url: o.startUrl,
    scope,
    display: o.display ?? "standalone",
    orientation: o.orientation ?? "portrait",
    theme_color: o.themeColor,
    background_color: o.backgroundColor,
    icons: o.icons,
    ...(o.shortcuts?.length ? { shortcuts: o.shortcuts } : {}),
  };
}

export interface ServiceWorkerOptions {
  /** Cache name prefix, e.g. "annina-app". Old caches with this prefix are deleted on update. */
  cachePrefix: string;
  /** Bump to throw away everything cached by older workers. */
  version: string;
  /** Absolute path the worker controls (base included, trailing slash), e.g. "/app/". */
  scope: string;
  /** Pages stored at install so the app opens offline the first time. Absolute paths. */
  precache: string[];
  /**
   * Same-origin path fragments that are NEVER cached and never answered by the
   * worker: the data API, the mock server, anything with a login in it.
   */
  bypass: string[];
}

/** The worker, as a string of plain JavaScript (no imports; it runs in a ServiceWorkerGlobalScope). */
export function serviceWorkerSource(o: ServiceWorkerOptions): string {
  const cfg = JSON.stringify({
    cache: `${o.cachePrefix}-${o.version}`, prefix: `${o.cachePrefix}-`, scope: o.scope, precache: o.precache, bypass: o.bypass,
  });
  return `// Generated by @factory/common/pwa. Do not edit; change the options and rebuild.
const CFG = ${cfg};

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CFG.cache);
    // One missing page must not stop the worker from installing.
    await Promise.all(CFG.precache.map((u) => cache.add(u).catch(() => {})));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith(CFG.prefix) && key !== CFG.cache) await caches.delete(key);
    await self.clients.claim();
  })());
});

const inScope = (url) => url.origin === self.location.origin && url.pathname.startsWith(CFG.scope);
const bypassed = (url) => CFG.bypass.some((b) => url.pathname.includes(b));
const storable = (res) => res && res.status === 200 && res.type === "basic";

async function put(request, response) {
  if (!storable(response)) return;
  const cache = await caches.open(CFG.cache);
  await cache.put(request, response);
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (!inScope(url) || bypassed(url)) return; // the browser handles it, untouched

  // Pages: the network first (she must see the current app after a deploy), the last copy when offline.
  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(request);
        event.waitUntil(put(request, fresh.clone()));
        return fresh;
      } catch {
        return (await caches.match(request, { ignoreSearch: true })) || (await caches.match(CFG.precache[0])) || Response.error();
      }
    })());
    return;
  }

  // Built assets have the hash in their name: once stored, never fetched again.
  if (url.pathname.includes("/_astro/")) {
    event.respondWith((async () => {
      const hit = await caches.match(request);
      if (hit) return hit;
      const fresh = await fetch(request);
      event.waitUntil(put(request, fresh.clone()));
      return fresh;
    })());
    return;
  }

  // Everything else (icons, manifest): show what is stored, refresh it behind.
  event.respondWith((async () => {
    const hit = await caches.match(request);
    const refresh = fetch(request).then(async (res) => { await put(request, res.clone()); return res; });
    if (hit) { event.waitUntil(refresh.catch(() => {})); return hit; }
    return refresh;
  })());
});
`;
}
